_root.主角函数.获取装备主动战技种类 = function(装备类型, 装备种类) {
    switch (装备种类) {
        case "刀":
            return "兵器";
        case "长枪":
            return "长枪";
        case "手部装备":
            return "空手";
        case "手枪":
            return 装备类型 == "手枪2" ? "手枪2" : "手枪";
    }
    return null;
}
